1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.util.E164PhoneNumbers;
12	
13	import java.time.LocalDate;
14	import java.time.Period;
15	import java.time.temporal.ChronoUnit;
16	import java.util.Collection;
17	import java.util.List;
18	import java.util.Map;
19	
20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "displayName",
27	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
28	    @Mapping(target = "initials",
29	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
30	            + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
31	    @Mapping(target = "membershipPoints",
32	        expression = "java(toMembershipPoints(owner))")
33	    @Mapping(target = "membershipLevel",
34	        expression = "java(toMembershipLevel(owner))")
35	    @Mapping(target = "locality",
36	        expression = "java(toLocality(owner))")
37	    @Mapping(target = "timezone",
38	        expression = "java(toTimezone(owner))")
39	    @Mapping(target = "contactPreference",
40	        expression = "java(toContactPreference(owner))")
41	    @Mapping(target = "identityKey",
42	        expression = "java(toIdentityKey(owner))")
43	    @Mapping(target = "checkDigit",
44	        expression = "java(toCheckDigit(owner))")
45	    @Mapping(target = "ageBand",
46	        expression = "java(toAgeBand(owner))")
47	    @Mapping(target = "telephoneDisplay",
48	        expression = "java(toTelephoneDisplay(owner))")
49	    @Mapping(target = "salutation",
50	        expression = "java(toSalutation(owner))")
51	    OwnerDto toOwnerDto(Owner owner);
52	
53	    /**
54	     * Derive an owner's salutation: the {@code title}, a single space, and the {@code lastName}
55	     * (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the salutation is
56	     * just the last name.
57	     */
58	    default String toSalutation(Owner owner) {
59	        String lastName = owner.getLastName();
60	        String title = owner.getTitle();
61	        if (title == null || title.isBlank()) {
62	            return lastName;
63	        }
64	        return title + " " + lastName;
65	    }
66	
67	    /**
68	     * Derive an owner's age band from the {@code birthDate} relative to the {@code registrationDate}:
69	     * 'MINOR' when under 18, 'ADULT' when 18 to 64, and 'SENIOR' when 65 or older. Returns
70	     * {@code null} when no birth date was supplied (the band is then absent from the DTO). When the
71	     * registration date is missing (e.g. legacy records) the current date is used as the reference.
72	     */
73	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
74	        LocalDate birthDate = owner.getBirthDate();
75	        if (birthDate == null) {
76	            return null;
77	        }
78	        LocalDate reference = owner.getRegistrationDate() != null
79	            ? owner.getRegistrationDate() : LocalDate.now();
80	        int age = Period.between(birthDate, reference).getYears();
81	        if (age < 18) {
82	            return OwnerDto.AgeBandEnum.MINOR;
83	        }
84	        if (age < 65) {
85	            return OwnerDto.AgeBandEnum.ADULT;
86	        }
87	        return OwnerDto.AgeBandEnum.SENIOR;
88	    }
89	
90	    /**
91	     * Format an owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
92	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
93	     * The raw {@code telephone} property is left untouched in E.164 form. Returns the value unchanged
94	     * when it is {@code null} or not in {@code '+'}-prefixed E.164 form.
95	     *
96	     * <p>The recognized dialling codes come from {@link E164PhoneNumbers}, the same table the create
97	     * endpoint validates against, so the two paths cannot diverge. When a number carries no recognized
98	     * code, a two-digit country code is assumed (the most common length).
99	     */
100	    default String toTelephoneDisplay(Owner owner) {
101	        String telephone = owner.getTelephone();
102	        if (telephone == null || !telephone.startsWith("+")) {
103	            return telephone;
104	        }
105	        String digits = telephone.substring(1);
106	        String code = E164PhoneNumbers.countryCode(digits)
107	            .filter(c -> digits.length() > c.length())
108	            .orElse(digits.length() > 2 ? digits.substring(0, 2) : digits);
109	        String national = digits.substring(code.length());
110	        StringBuilder sb = new StringBuilder("+").append(code);
111	        for (int i = 0; i < national.length(); i += 3) {
112	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
113	        }
114	        return sb.toString();
115	    }
116	
117	    /**
118	     * Derive an owner's check digit: a single Luhn check digit (0-9) computed over the digits
119	     * contained in the {@code customerCode}. Non-digit characters (the separators) are ignored.
120	     */
121	    default Integer toCheckDigit(Owner owner) {
122	        String code = owner.getCustomerCode();
123	        if (code == null) {
124	            return null;
125	        }
126	        int sum = 0;
127	        boolean dbl = true;
128	        for (int i = code.length() - 1; i >= 0; i--) {
129	            char c = code.charAt(i);
130	            if (c < '0' || c > '9') {
131	                continue;
132	            }
133	            int d = c - '0';
134	            if (dbl) {
135	                d *= 2;
136	                if (d > 9) {
137	                    d -= 9;
138	                }
139	            }
140	            sum += d;
141	            dbl = !dbl;
142	        }
143	        return (10 - (sum % 10)) % 10;
144	    }
145	
146	    /**
147	     * Derive an owner's duplicate-detection identity key: the normalized E.164 telephone, the
148	     * lower-cased email (empty when none), and the household id (empty when none), joined with
149	     * {@code '|'}. Two owners are duplicates only when their whole identity keys are equal.
150	     *
151	     * <p>This is the single source of truth for the key: it is both returned on the DTO and used by
152	     * the create endpoint's 409 duplicate check, so the value clients see is exactly the value that
153	     * governs rejection. The "email present" rule reuses {@link #hasEmail(Owner)}.
154	     */
155	    default String toIdentityKey(Owner owner) {
156	        String email = hasEmail(owner) ? owner.getEmail() : "";
157	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
158	        return owner.getTelephone() + "|" + email + "|" + household;
159	    }
160	
161	    /**
162	     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
163	     * for the "is an email present" rule shared by the derived fields below.
164	     */
165	    default boolean hasEmail(Owner owner) {
166	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
167	    }
168	
169	    /**
170	     * Derive an owner's preferred contact channel: 'EMAIL' when an email address is present,
171	     * otherwise 'PHONE'.
172	     */
173	    default String toContactPreference(Owner owner) {
174	        return hasEmail(owner) ? "EMAIL" : "PHONE";
175	    }
176	
177	    /**
178	     * Derive an owner's membership points: start at 0; add 2 when an email address is present; add 1
179	     * when the owner has no namesakes (namesakeCount is 0); add 2 when the owner belongs to a
180	     * household of 3 or more (see {@link #hasHouseholdBonus(Owner)}); add 3 when the owner's tenure
181	     * exceeds 365 days (see {@link #hasTenureBonus(Owner)}). Because a newly created owner has zero
182	     * tenure it never earns the tenure points, so a new owner with an email and no namesakes in a
183	     * single-member household scores 3 points.
184	     */
185	    default Integer toMembershipPoints(Owner owner) {
186	        int points = 0;
187	        if (hasEmail(owner)) {
188	            points += 2;
189	        }
190	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
191	        if (noNamesakes) {
192	            points += 1;
193	        }
194	        if (hasHouseholdBonus(owner)) {
195	            points += 2;
196	        }
197	        if (hasTenureBonus(owner)) {
198	            points += 3;
199	        }
200	        return points;
201	    }
202	
203	    /**
204	     * Whether the owner belongs to a household of 3 or more members. The household size is the count
205	     * of owners sharing the owner's household id, frozen at creation (see the create endpoint).
206	     * Returns {@code false} when no household size is present (e.g. legacy records).
207	     */
208	    default boolean hasHouseholdBonus(Owner owner) {
209	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
210	    }
211	
212	    /**
213	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
214	     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
215	     * or more.
216	     */
217	    default Integer toMembershipLevel(Owner owner) {
218	        int points = toMembershipPoints(owner);
219	        if (points <= 1) {
220	            return 1;
221	        }
222	        if (points <= 3) {
223	            return 2;
224	        }
225	        if (points <= 5) {
226	            return 3;
227	        }
228	        return 4;
229	    }
230	
231	    /**
232	     * Whether the owner's tenure exceeds 365 days, i.e. more than a year has elapsed between the
233	     * {@code registrationDate} and the current date. A brand-new owner (registered today) has zero
234	     * tenure and so never qualifies. Returns {@code false} when no registration date is present.
235	     */
236	    default boolean hasTenureBonus(Owner owner) {
237	        LocalDate registrationDate = owner.getRegistrationDate();
238	        if (registrationDate == null) {
239	            return false;
240	        }
241	        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365;
242	    }
243	
244	    /**
245	     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
246	     */
247	    Map<String, String> CITY_REGION = Map.of(
248	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
249	
250	    /**
251	     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
252	     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
253	     * inclusive.
254	     */
255	    Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
256	        "NSW", new int[] {2000, 2099},
257	        "VIC", new int[] {3000, 3099},
258	        "QLD", new int[] {4000, 4099});
259	
260	    /**
261	     * Derive an owner's locality (region) from the region-and-hash customer code: the {@code <REGION>}
262	     * segment of the {@code customerCode}, i.e. everything before the first {@code '-'}. Since the
263	     * region is baked into the customer code at creation (see the create endpoint), the locality now
264	     * moves with that identity rather than being recomputed from the postcode and city. When an owner
265	     * has no customer code yet (e.g. legacy records), fall back to deriving the region directly via
266	     * {@link #regionOf(Owner)}.
267	     */
268	    default String toLocality(Owner owner) {
269	        String code = owner.getCustomerCode();
270	        if (code != null) {
271	            int dash = code.indexOf('-');
272	            if (dash > 0) {
273	                return code.substring(0, dash);
274	            }
275	        }
276	        return regionOf(owner);
277	    }
278	
279	    /**
280	     * Fixed region-to-IANA-timezone table used to derive an owner's timezone: NSW -> Australia/Sydney,
281	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane.
282	     */
283	    Map<String, String> REGION_TIMEZONE = Map.of(
284	        "NSW", "Australia/Sydney",
285	        "VIC", "Australia/Melbourne",
286	        "QLD", "Australia/Brisbane");
287	
288	    /**
289	     * Derive an owner's IANA timezone name from its locality/region (see {@link #toLocality(Owner)})
290	     * via the fixed {@link #REGION_TIMEZONE} table. Returns {@code null} when the region resolves to no
291	     * entry in the table (e.g. 'UNKNOWN'), so the timezone is then absent from the DTO.
292	     */
293	    default String toTimezone(Owner owner) {
294	        return REGION_TIMEZONE.get(toLocality(owner));
295	    }
296	
297	    /**
298	     * Derive an owner's region, preferring the postcode: when the postcode is present and falls within
299	     * a known region's range (see {@link #REGION_POSTCODE_RANGES}) that region wins. When the postcode
300	     * is absent or in no known range, fall back to the fixed {@link #CITY_REGION} table. Returns
